svg.script:
(()=>{
const data=[{"name": "Hot singleton resolve", "values": ["6.233", "10.954", "40.425", "41.525", "81.354", "71.729", "48.354"]}, {"name": "Transient resolve", "values": ["41.798", "79.566", "219.82", "227.15", "301.40", "519.75", "138.05"]}, {"name": "Deep graph (10 levels)", "values": ["344.21", "397.37", "1306.3", "1190.8", "1463.0", "4478.8", "717.75"]}, {"name": "Wide graph (4 dependencies)", "values": ["59.584", "103.22", "331.10", "302.69", "457.97", "863.32", "197.63"]}, {"name": "Wide graph (10 dependencies)", "values": ["188.37", "394.63", "681.08", "571.54", "979.46", "2234.1", "321.29"]}, {"name": "Registration", "values": ["2007.5", "61274.6", "74763.4", "95225.6", "3762.9", null, "3593.3"]}, {"name": "First resolve", "values": ["653.13", "9967.4", "2434.9", "3044.2", "1236.8", "3322.9", "1275.3"]}, {"name": "Scope creation", "values": ["79.750", "6194.4", "1054.4", "1031.2", "503.26", "419.38", "164.08"]}, {"name": "First scoped resolve", "values": ["115.05", "3048.6", "352.92", "362.54", "373.54", "296.08", "203.05"]}, {"name": "Warm scoped resolve", "values": ["8.387", "30.204", "90.841", "95.242", "78.375", "92.630", "7.975"]}, {"name": "Sync teardown", "values": ["99.455", null, null, null, null, "124.21", null]}, {"name": "Async teardown", "values": ["242.91", null, "860.52", "886.87", "1311.8", null, "721.42"]}, {"name": "Lazy resolve", "values": ["18.837", "64.212", "115.68", "124.09", "155.01", "271.06", "76.496"]}];
const names=["InferDI", "InversifyJS", "Awilix PROXY", "Awilix CLASSIC", "TSyringe", "TypeDI", "Typed Inject"];
const tabs=Array.from(document.querySelectorAll('.tab'));
const rows=names.map((_,i)=>{const el=document.getElementById('row-'+i);return {el,bar:el.querySelector('.bar'),label:el.querySelector('.value'),title:el.querySelector('title'),y:+el.getAttribute('transform').match(/[\d.]+/g)[1],w:+el.querySelector('.bar').getAttribute('width'),v:+data[0].values[i]};});
let active=0,frame=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function select(index,animate=true){
 cancelAnimationFrame(frame);active=index;
 const scene=data[index], max=Math.max(...scene.values.map(v=>+(v||0)));
 const order=names.map((_,i)=>i).sort((a,b)=>(scene.values[a]===null?Infinity:+scene.values[a])-(scene.values[b]===null?Infinity:+scene.values[b])||a-b);
 document.getElementById('scenario').textContent=scene.name;
 document.getElementById('chart').setAttribute('aria-labelledby','tab-'+index);
 tabs.forEach((t,i)=>{t.setAttribute('aria-selected',String(i===index));t.setAttribute('tabindex',i===index?'0':'-1');});
 for(let i=0;i<5;i++)document.getElementById('tick-'+i).textContent=(max*i/4).toLocaleString('en-US',{maximumFractionDigits:2,useGrouping:false});
 const start=rows.map(r=>({y:r.y,w:r.w,v:r.v}));
 const end=rows.map((r,i)=>({y:405+order.indexOf(i)*57,w:scene.values[i]===null?0:+scene.values[i]/max*820,v:scene.values[i]===null?0:+scene.values[i]}));
 const duration=animate&&!reduced.matches?850:0;let began=null;
 rows.forEach((r,i)=>{r.title.textContent=names[i]+': '+(scene.values[i]===null?'N/A':scene.values[i]+' ns/op');r.el.setAttribute('aria-label',r.title.textContent);});
 function draw(now){
 if(began===null)began=now;
 const t=duration?Math.min((now-began)/duration,1):1, p=1-Math.pow(1-t,3);
 rows.forEach((r,i)=>{
 const a=start[i],b=end[i];r.y=a.y+(b.y-a.y)*p;r.w=a.w+(b.w-a.w)*p;r.v=a.v+(b.v-a.v)*p;
 r.el.setAttribute('transform','translate(0 '+r.y+')');r.bar.setAttribute('width',r.w);
 r.label.setAttribute('x',252+r.w);
 r.label.textContent=scene.values[i]===null?'N/A':t===1?scene.values[i]:r.v.toFixed(scene.values[i].split('.')[1].length);
 r.label.setAttribute('fill',scene.values[i]===null?'#91a0b7':'#e6edf5');
 });
 if(t<1)frame=requestAnimationFrame(draw);
 }
 frame=requestAnimationFrame(draw);
}
tabs.forEach((tab,i)=>{
 tab.addEventListener('click',()=>select(i));
 tab.addEventListener('keydown',e=>{
 let next=i;
 if(e.key==='ArrowRight'||e.key==='ArrowDown')next=(i+1)%tabs.length;
 else if(e.key==='ArrowLeft'||e.key==='ArrowUp')next=(i+tabs.length-1)%tabs.length;
 else if(e.key==='Home')next=0;
 else if(e.key==='End')next=tabs.length-1;
 else if(e.key!=='Enter'&&e.key!==' ')return;
 e.preventDefault();tabs[next].focus();select(next);
 });
});
select(0,false);
})();
